  ('rare', 'Raro', 3, '#2F6FA8', 'Itens de sacerdotes, profetas e funções especiais, incluindo mantos e vestes cerimoniais.', true),
  ('epic', 'Épico', 4, '#8A3FA0', 'Itens ligados a personagens e acontecimentos marcantes da Bíblia.', true),
  ('legendary', 'Lendário', 5, '#C9771A', 'Um equipamento exclusivo para cada um dos 66 livros, conquistado gratuitamente ao concluir o livro.', true),
  ('holy', 'Santo', 6, '#B8932F', 'Artefatos sagrados e representações simbólicas das obras de Deus, exibidos no Santuário das Conquistas.', true)
